import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import datetime
import os

# Load data
df = pd.read_csv('/app/benchmark/data.csv')

# Ensure correct data types
df['Sale_Date'] = pd.to_datetime(df['Sale_Date'])
df['Profit_Margin_USD'] = df['Resale_Price_USD'] - df['Retail_Price_USD']
df['Resale_to_Retail_Ratio'] = df['Resale_Price_USD'] / df['Retail_Price_USD']
df['Is_Premium'] = df['Profit_Margin_USD'] > 0

# KPIs
avg_profit_margin = df['Profit_Margin_USD'].mean()
resale_premium_rate = df['Is_Premium'].mean() * 100
avg_days_in_inventory = df['Days_in_Inventory'].mean()
avg_resale_to_retail_ratio = df['Resale_to_Retail_Ratio'].mean()
top_performing_colorway_margin = df.groupby('Colorway')['Profit_Margin_USD'].mean().max()
top_performing_colorway_name = df.groupby('Colorway')['Profit_Margin_USD'].mean().idxmax()

# Helper function to embed plots
def plot_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight')
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# Section 1: Overview
total_transactions = len(df)
date_range = f"{df['Sale_Date'].min().strftime('%Y-%m-%d')} to {df['Sale_Date'].max().strftime('%Y-%m-%d')}"
avg_retail = df['Retail_Price_USD'].mean()
avg_resale = df['Resale_Price_USD'].mean()

fig, ax = plt.subplots(figsize=(8, 5))
sns.histplot(df['Profit_Margin_USD'], bins=50, kde=True, ax=ax)
ax.set_title('Distribution of Profit Margin (USD)')
ax.set_xlabel('Profit Margin (USD)')
ax.set_ylabel('Frequency')
overview_plot = plot_to_base64(fig)

# Section 2: Model & Colorway Analysis
model_perf = df.groupby('Shoe_Model').agg({
    'Resale_Price_USD': 'mean',
    'Profit_Margin_USD': 'mean',
    'Transaction_ID': 'count'
}).rename(columns={'Transaction_ID': 'Volume'}).sort_values('Profit_Margin_USD', ascending=False)

fig, ax = plt.subplots(figsize=(10, 6))
sns.barplot(data=model_perf.reset_index(), x='Profit_Margin_USD', y='Shoe_Model', ax=ax, palette='viridis')
ax.set_title('Average Profit Margin by Shoe Model')
ax.set_xlabel('Avg Profit Margin (USD)')
ax.set_ylabel('Shoe Model')
model_plot = plot_to_base64(fig)

colorway_perf = df.groupby('Colorway').agg({
    'Profit_Margin_USD': 'mean',
    'Transaction_ID': 'count'
}).rename(columns={'Transaction_ID': 'Volume'}).sort_values('Profit_Margin_USD', ascending=False)

fig, ax = plt.subplots(figsize=(10, 6))
sns.barplot(data=colorway_perf.reset_index().head(10), x='Profit_Margin_USD', y='Colorway', ax=ax, palette='magma')
ax.set_title('Top 10 Colorways by Average Profit Margin')
ax.set_xlabel('Avg Profit Margin (USD)')
ax.set_ylabel('Colorway')
colorway_plot = plot_to_base64(fig)

# Section 3: Condition Impact
condition_perf = df.groupby('Condition').agg({
    'Resale_Price_USD': 'mean',
    'Profit_Margin_USD': 'mean',
    'Is_Premium': 'mean'
}).rename(columns={'Is_Premium': 'Premium_Rate'})
condition_perf['Premium_Rate'] *= 100

fig, ax = plt.subplots(figsize=(8, 5))
sns.boxplot(data=df, x='Condition', y='Profit_Margin_USD', ax=ax, palette='Set2')
ax.set_title('Profit Margin by Shoe Condition')
ax.set_xlabel('Condition')
ax.set_ylabel('Profit Margin (USD)')
condition_plot = plot_to_base64(fig)

# Section 4: Channel Performance & Inventory Velocity
channel_perf = df.groupby('Sales_Channel').agg({
    'Resale_Price_USD': 'mean',
    'Profit_Margin_USD': 'mean',
    'Days_in_Inventory': 'mean'
}).sort_values('Profit_Margin_USD', ascending=False)

fig, ax = plt.subplots(figsize=(10, 6))
sns.scatterplot(data=channel_perf.reset_index(), x='Days_in_Inventory', y='Profit_Margin_USD',
                hue='Sales_Channel', s=200, ax=ax, palette='tab10')
for i, row in channel_perf.reset_index().iterrows():
    ax.text(row['Days_in_Inventory'] + 0.5, row['Profit_Margin_USD'], row['Sales_Channel'])
ax.set_title('Channel Performance: Profit Margin vs Days in Inventory')
ax.set_xlabel('Average Days in Inventory')
ax.set_ylabel('Average Profit Margin (USD)')
channel_plot = plot_to_base64(fig)

# Section 5: Temporal Trends & Seasonality
df['YearMonth'] = df['Sale_Date'].dt.to_period('M')
monthly_perf = df.groupby('YearMonth').agg({
    'Profit_Margin_USD': 'mean',
    'Transaction_ID': 'count'
}).rename(columns={'Transaction_ID': 'Volume'})

fig, ax1 = plt.subplots(figsize=(12, 6))
ax2 = ax1.twinx()
sns.lineplot(data=monthly_perf.reset_index(), x=monthly_perf.index.astype(str), y='Profit_Margin_USD', ax=ax1, color='blue', marker='o')
sns.barplot(data=monthly_perf.reset_index(), x=monthly_perf.index.astype(str), y='Volume', ax=ax2, alpha=0.3, color='gray')
ax1.set_xticklabels(monthly_perf.index.astype(str), rotation=45, ha='right')
ax1.set_title('Monthly Trends: Average Profit Margin and Transaction Volume')
ax1.set_xlabel('Month')
ax1.set_ylabel('Average Profit Margin (USD)', color='blue')
ax2.set_ylabel('Transaction Volume', color='gray')
temporal_plot = plot_to_base64(fig)

